"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import Header from "@/components/common/Header";
import Navbar from "@/components/common/Navbar";
import Footer from "@/components/common/Footer";
import AdminSidebarPanel from "@/components/common/AdminSidebar";
import axios from "axios";
import Dialog from "@/components/ui/Dialog";
import { useSession } from "next-auth/react";

const BACKEND_URL = process.env.NEXT_PUBLIC_BACKEND_URL;

interface Admin {
  id: number;
  fullname: string;
  email: string;
  role: string;
  password?: string;
}

const AdminPage = () => {
  const { data: session, status } = useSession();
  const [admins, setAdmins] = useState<Admin[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [newAdmin, setNewAdmin] = useState<Omit<Admin, "id">>({
    fullname: "",
    email: "",
    role: "",
    password: "",
  });
  const [editingAdmin, setEditingAdmin] = useState<Admin | null>(null);
  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);
  const router = useRouter();

  useEffect(() => {
    if (status === "loading") return;
    if (!session) {
      router.push("/dashboard");
    } else {
      fetchAdmins();
    }
  }, [session, status]);

  const fetchAdmins = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get<Admin[]>(`${BACKEND_URL}/api/v1/admin`);
      setAdmins(response.data);
    } catch (err) {
      setError("Failed to fetch admins");
    } finally {
      setLoading(false);
    }
  };

  const createAdmin = async () => {
    try {
      await axios.post(`${BACKEND_URL}/api/v1/admin`, newAdmin);
      setNewAdmin({ fullname: "", email: "", role: "", password: "" });
      fetchAdmins();
    } catch (err) {
      console.error("Failed to create admin", err);
    }
  };

  const updateAdmin = async () => {
    try {
      if (editingAdmin) {
        console.log("Updating admin:", editingAdmin);
  
        const payload = {
          email: editingAdmin.email || undefined,
          fullname: editingAdmin.fullname || undefined,
          password: editingAdmin.password || undefined,
          role: editingAdmin.role || undefined
        };
  
        await axios.put(`${BACKEND_URL}/api/v1/admin/${editingAdmin.id}`, payload);
        setEditingAdmin(null);
        setIsModalOpen(false);
      }
      fetchAdmins();
    } catch (err) {
      console.error("Failed to update admin", err);
      setError("Failed to update admin");
    }
  };
  

  const deleteAdmin = async (id: number) => {
    try {
      await axios.delete(`${BACKEND_URL}/api/v1/admin/${id}`);
      fetchAdmins();
    } catch (err) {
      console.error("Failed to delete admin", err);
    }
  };


  return (
    <div className="flex min-h-screen flex-col bg-gray-100 text-black">
      <Header />
      <Navbar />
      <div className="flex flex-grow">
        <AdminSidebarPanel />
        <main className="flex-grow p-6 bg-white shadow-md rounded-xl">
          <h1 className="text-2xl font-bold mb-4">👤 Admin Management</h1>
          {error && <div className="text-red-500 mb-4">{error}</div>}

          {/* Add Admin Form */}
          <div className="p-4 bg-gray-50 shadow-md rounded-xl border border-gray-200">
            <h2 className="text-lg font-semibold mb-2">➕ Add New Admin</h2>
            <input type="text" placeholder="Fullname" className="input-field" value={newAdmin.fullname} onChange={(e) => setNewAdmin({ ...newAdmin, fullname: e.target.value })} />
            <input type="email" placeholder="Email" className="input-field" value={newAdmin.email} onChange={(e) => setNewAdmin({ ...newAdmin, email: e.target.value })} />
            <input type="text" placeholder="Role" className="input-field" value={newAdmin.role} onChange={(e) => setNewAdmin({ ...newAdmin, role: e.target.value })} />
            <input type="password" placeholder="Password" className="input-field" value={newAdmin.password} onChange={(e) => setNewAdmin({ ...newAdmin, password: e.target.value })} />
            <button className="btn-primary" onClick={createAdmin}>Create Admin</button>
          </div>

          {/* Admin List */}
          {loading ? (
            <p className="text-center text-gray-500 mt-4">Loading...</p>
          ) : (
            <ul className="mt-4">
              {admins.length > 0 ? (
                admins.map((admin) => (
                  <li key={admin.id} className="mt-2 p-4 rounded-xl border shadow-sm hover:shadow-md transition bg-white border-gray-300">
                    <h3 className="font-semibold text-lg">{admin.fullname} ({admin.role})</h3>
                    <p className="text-gray-700">{admin.email}</p>
                    <div className="mt-3 flex gap-3">
                      <button className="btn-edit" onClick={() => { setEditingAdmin(admin); setIsModalOpen(true); }}>Edit</button>
                      <button className="btn-delete" onClick={() => deleteAdmin(admin.id)}>Delete</button>
                    </div>
                  </li>
                ))
              ) : (
                <p className="text-gray-500">No admins found.</p>
              )}
            </ul>
          )}
        </main>
      </div>
      <Footer />

      {/* Edit Modal */}
      {isModalOpen && editingAdmin && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50">
          <div className="bg-white p-6 rounded-lg shadow-lg w-96">
            <h2 className="text-xl font-semibold mb-4">✏️ Edit Admin</h2>
            <input type="text" placeholder="Fullname" className="input-field" value={editingAdmin.fullname} onChange={(e) => setEditingAdmin({ ...editingAdmin, fullname: e.target.value })} />
            <input type="email" placeholder="Email" className="input-field" value={editingAdmin.email} onChange={(e) => setEditingAdmin({ ...editingAdmin, email: e.target.value })} />
            <input type="text" placeholder="Role" className="input-field" value={editingAdmin.role} onChange={(e) => setEditingAdmin({ ...editingAdmin, role: e.target.value })} />
            <input type="password" placeholder="Password" className="input-field" value={editingAdmin.password || ""} onChange={(e) => setEditingAdmin({ ...editingAdmin, password: e.target.value })} />
            <div className="flex justify-end gap-2 mt-4">
              <button className="btn-cancel" onClick={() => setIsModalOpen(false)}>Cancel</button>
              <button className="btn-primary" onClick={updateAdmin}>Save</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminPage;
